CREATE TABLE IF NOT EXISTS "settings" ("id" serial PRIMARY KEY, "legal_name" text NOT NULL, "abn" varchar(14) NOT NULL, "gst_status" varchar(20) DEFAULT 'unconfirmed' NOT NULL, "gst_effective_date" date, "contact_email" text, "paypal_url" text, "updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "customers" ("id" serial PRIMARY KEY, "kind" varchar(20) NOT NULL, "name" text NOT NULL, "email" text, "phone" text, "created_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "users" ("id" serial PRIMARY KEY, "email" text NOT NULL UNIQUE, "role" varchar(20) NOT NULL, "customer_id" integer, "revoked_at" timestamptz, "created_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "service_requests" ("id" serial PRIMARY KEY, "reference" varchar(30) NOT NULL UNIQUE, "customer_id" integer, "category" text NOT NULL, "description" text NOT NULL, "preference" varchar(20) NOT NULL, "urgency" varchar(20) NOT NULL, "status" varchar(30) DEFAULT 'new' NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "jobs" ("id" serial PRIMARY KEY, "customer_id" integer NOT NULL, "request_id" integer, "status" varchar(30) DEFAULT 'new' NOT NULL, "priority" varchar(20) DEFAULT 'normal' NOT NULL, "due_date" date, "completion_notes" text, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "quotes" ("id" serial PRIMARY KEY, "job_id" integer NOT NULL, "version" integer NOT NULL, "reference" varchar(30) NOT NULL, "status" varchar(20) DEFAULT 'draft' NOT NULL, "valid_until" date, "terms_snapshot" jsonb, "totals" jsonb, "accepted_at" timestamptz, "accepted_by" integer, "created_at" timestamptz DEFAULT now() NOT NULL, UNIQUE("job_id","version"));
CREATE TABLE IF NOT EXISTS "quote_lines" ("id" serial PRIMARY KEY, "quote_id" integer NOT NULL, "description" text NOT NULL, "quantity" integer NOT NULL, "unit_cents" integer NOT NULL, "discount_cents" integer DEFAULT 0 NOT NULL, "gst_rate" integer DEFAULT 10 NOT NULL);
CREATE TABLE IF NOT EXISTS "invoices" ("id" serial PRIMARY KEY, "job_id" integer NOT NULL, "quote_id" integer, "number" varchar(30) NOT NULL UNIQUE, "status" varchar(20) DEFAULT 'draft' NOT NULL, "net_cents" integer NOT NULL, "gst_cents" integer NOT NULL, "gross_cents" integer NOT NULL, "allocated_cents" integer DEFAULT 0 NOT NULL, "due_date" date, "customer_snapshot" jsonb NOT NULL, "business_snapshot" jsonb NOT NULL, "terms_snapshot" jsonb NOT NULL, "issued_at" timestamptz, "created_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "payments" ("id" serial PRIMARY KEY, "invoice_id" integer NOT NULL, "provider" varchar(20) NOT NULL, "external_reference" text, "gross_cents" integer NOT NULL, "fee_cents" integer DEFAULT 0 NOT NULL, "net_cents" integer NOT NULL, "status" varchar(20) DEFAULT 'pending' NOT NULL, "paid_at" timestamptz, "created_at" timestamptz DEFAULT now() NOT NULL, UNIQUE("provider","external_reference"));
CREATE TABLE IF NOT EXISTS "attachments" ("id" serial PRIMARY KEY, "customer_id" integer, "storage_key" text NOT NULL, "filename" text NOT NULL, "mime_type" text NOT NULL, "size" integer NOT NULL, "sha256" varchar(64) NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "outbox" ("id" serial PRIMARY KEY, "dedupe_key" varchar(200) NOT NULL UNIQUE, "type" varchar(40) NOT NULL, "payload" jsonb NOT NULL, "status" varchar(20) DEFAULT 'pending' NOT NULL, "attempts" integer DEFAULT 0 NOT NULL, "available_at" timestamptz DEFAULT now() NOT NULL, "last_error" text, "created_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "audit_events" ("id" serial PRIMARY KEY, "actor_id" integer, "action" text NOT NULL, "entity_type" text NOT NULL, "entity_id" integer, "metadata" jsonb, "created_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "sessions" ("id" serial PRIMARY KEY, "user_id" integer NOT NULL, "token_hash" varchar(128) NOT NULL UNIQUE, "expires_at" timestamptz NOT NULL, "revoked_at" timestamptz);
CREATE TABLE IF NOT EXISTS "demo_marker" ("id" serial PRIMARY KEY, "is_demo" boolean DEFAULT true NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "service_categories" ("id" serial PRIMARY KEY, "name" text NOT NULL, "active" boolean DEFAULT true NOT NULL);
CREATE TABLE IF NOT EXISTS "rate_catalogue" ("id" serial PRIMARY KEY, "category_id" integer, "description" text NOT NULL, "unit_cents" integer NOT NULL, "active" boolean DEFAULT true NOT NULL);
CREATE TABLE IF NOT EXISTS "contacts" ("id" serial PRIMARY KEY, "customer_id" integer NOT NULL, "name" text NOT NULL, "email" text, "phone" text);
CREATE TABLE IF NOT EXISTS "service_locations" ("id" serial PRIMARY KEY, "customer_id" integer NOT NULL, "label" text NOT NULL, "address" text NOT NULL);
CREATE TABLE IF NOT EXISTS "devices" ("id" serial PRIMARY KEY, "customer_id" integer NOT NULL, "description" text NOT NULL, "serial_number" text);
CREATE TABLE IF NOT EXISTS "tickets" ("id" serial PRIMARY KEY, "customer_id" integer NOT NULL, "job_id" integer, "subject" text NOT NULL, "status" varchar(20) DEFAULT 'open' NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "messages" ("id" serial PRIMARY KEY, "ticket_id" integer NOT NULL, "author_id" integer NOT NULL, "body" text NOT NULL, "visibility" varchar(20) DEFAULT 'customer' NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "job_tasks" ("id" serial PRIMARY KEY, "job_id" integer NOT NULL, "title" text NOT NULL, "completed" boolean DEFAULT false NOT NULL);
CREATE TABLE IF NOT EXISTS "appointments" ("id" serial PRIMARY KEY, "job_id" integer NOT NULL, "starts_at" timestamptz NOT NULL, "ends_at" timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS "time_entries" ("id" serial PRIMARY KEY, "job_id" integer NOT NULL, "minutes" integer NOT NULL, "unit_cents" integer NOT NULL, "invoice_id" integer);
CREATE TABLE IF NOT EXISTS "material_entries" ("id" serial PRIMARY KEY, "job_id" integer NOT NULL, "description" text NOT NULL, "quantity" integer NOT NULL, "unit_cents" integer NOT NULL, "invoice_id" integer);
CREATE TABLE IF NOT EXISTS "expenses" ("id" serial PRIMARY KEY, "job_id" integer, "description" text NOT NULL, "amount_cents" integer NOT NULL, "attachment_id" integer);
CREATE TABLE IF NOT EXISTS "invoice_lines" ("id" serial PRIMARY KEY, "invoice_id" integer NOT NULL, "description" text NOT NULL, "quantity" integer NOT NULL, "unit_cents" integer NOT NULL, "gst_rate" integer NOT NULL);
CREATE TABLE IF NOT EXISTS "document_sequences" ("id" serial PRIMARY KEY, "document_type" varchar(20) NOT NULL UNIQUE, "next_value" integer DEFAULT 1 NOT NULL);
CREATE TABLE IF NOT EXISTS "credit_notes" ("id" serial PRIMARY KEY, "invoice_id" integer NOT NULL, "number" varchar(30) NOT NULL UNIQUE, "amount_cents" integer NOT NULL, "reason" text NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "receipts" ("id" serial PRIMARY KEY, "payment_id" integer NOT NULL, "number" varchar(30) NOT NULL UNIQUE, "issued_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "webhook_events" ("id" serial PRIMARY KEY, "provider" varchar(20) NOT NULL, "event_id" text NOT NULL, "payload" jsonb NOT NULL, "occurred_at" timestamptz, "processed_at" timestamptz, UNIQUE("provider","event_id"));
